# incumbent_refit.top1, final.logistic.top1, final.model.top1), compared at the 4-decimal precision the accuracies
# are banked at.
REFERENCE_TOP1 = {'incumbent': 0.2395, 'logistic_l3': 0.2317, 'model': 0.2884}
REPRODUCTION_TOLERANCE, NULL_TOLERANCE, CHANCE = 0.005, 0.01, 0.038462
BAR = 0.05
N_EXT, N_REAL = 61409, 38452
# The clause is read on EXACT counts over the real-family rows: M4's correct real-family rows, recomputed here from its
# per-example vector and the sealed family array, must reach ceil(N_REAL x (1/26 + BAR)) = MIN_CORRECT_REAL. The
# eight-family mixture against MIN_CORRECT = ceil(N_EXT x (1/26 + BAR)) is a flag.
MIN_CORRECT_REAL = 3402
MIN_CORRECT = 5433
MIXTURE_MUST_REACH = 0.088462   # the bar restated as an accuracy, 6 decimals
MAX_ITER = {"incumbent": 200, "logistic_l3": 1000, "model": 250}
ENV = {"threads": 3, "nice": 10, "sklearn": "1.9.0", "numpy": "2.4.6", "python": "3.11.15"}
SEED = 20260825
ROLES = ["incumbent", "logistic_l3", "model"]
ORDER = ["null"] + ROLES


def canon(obj) -> str:
    return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)


def sha_obj(obj) -> str:
    return hashlib.sha256(canon(obj).encode("utf-8")).hexdigest()


def fingerprint(**parts) -> str:
    return sha_obj(parts)[:16]


def _write(result):
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w", encoding="utf-8") as fh:
        json.dump(result, fh, indent=2, sort_keys=True)
        fh.write("\n")


def main() -> int:
    if os.path.exists(OUT):
        os.remove(OUT)   # a stale verdict never survives a reader run that emits none
    if os.path.exists(NOT_RUN):
        # the runner files NOT RUN after it has written an in-progress artifact (a failed null control, a reproduction
        # drift): the marker takes precedence over any artifact beside it, and no verdict is emitted (stop rule 4)
        try:
            nr = json.load(open(NOT_RUN, encoding="utf-8"))
            print(f"READER 0019: NOT RUN — {nr.get('reason')!r} (stage {nr.get('stage')}, filed {nr.get('utc')}, "
                  f"{nr.get('n_checkpoints')} checkpoints). A NOT RUN is not a verdict.", file=sys.stderr)
        except Exception:  # noqa: BLE001
            print("READER 0019: NOT RUN file present but unreadable.", file=sys.stderr)
        return 2
    if not os.path.exists(ARTIFACT):
        print(f"READER 0019: artifact absent: {os.path.relpath(ARTIFACT, REPO)}\n  Absence is not a pass. No verdict emitted.",
              file=sys.stderr)
        return 2
    try:
        d = json.load(open(ARTIFACT, encoding="utf-8"))
    except Exception as e:  # noqa: BLE001
        print(f"READER 0019: artifact malformed ({type(e).__name__}: {e}).", file=sys.stderr)
        return 2
    try:
        return read(d)
    except Exception as e:  # noqa: BLE001
        # an artifact of unexpected shape is VOID, never a traceback that leaves no verdict behind
        result = {"schema": "raise-v1/oob_4096_reread_verdict/1", "preregistration": REREAD, "reads_artifact_of": PREREG,
                  "source_artifact": os.path.relpath(ARTIFACT, REPO), "verdict": "VOID",
                  "meaning": "The artifact has an unexpected shape; nothing is counted in either direction.",
                  "validity_failed_clauses": [f"reader: artifact of unexpected shape ({type(e).__name__}: {e})"],
                  "transfer_failed_clauses": [], "establishes_a_buyer": False}
        _write(result)
        print(f"READER 0019 — VOID: artifact of unexpected shape ({type(e).__name__}: {e})\n  wrote {os.path.relpath(OUT, REPO)}")
        return 0


def read(d) -> int:
    g = d.get
    void: list[str] = []

    def num(v):
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            return None
        return v if math.isfinite(v) else None

    def expect_eq(where, got, want, label):
        if got != want:
            where.append(f"{label}={got!r}, preregistered {want!r}")

    def _ints(v, n, values=None):
        return isinstance(v, list) and len(v) == n and all(
            isinstance(x, int) and not isinstance(x, bool) and (values is None or x in values) for x in v)

    mean4 = lambda xs: round(sum(xs) / len(xs), 4) if xs else None  # noqa: E731

    # ---- scope
    if g("preregistration") != PREREG:
        void.append(f"scope: preregistration={g('preregistration')!r}, this reader is frozen for {PREREG}")
    if g("smoke") is not False:
        void.append(f"scope: smoke={g('smoke')!r}; a smoke run is not the preregistered run")
    if g("stage") != "run":
        void.append(f"scope: stage={g('stage')!r}")
    corpus = g("corpus") or {}
    for k, v in CORPUS.items():
        expect_eq(void, corpus.get(k), v, f"scope: corpus.{k}")
    if g("n_classes") != 26 or num(g("chance_accuracy")) != CHANCE:
        void.append(f"scope: n_classes={g('n_classes')!r}, chance_accuracy={g('chance_accuracy')!r}")
    proto = g("protocol") or {}
    for k in sorted(set(PROTOCOL) | set(proto)):
        if proto.get(k) != PROTOCOL.get(k):
            void.append(f"scope: protocol.{k}={proto.get(k)!r}, preregistered {PROTOCOL.get(k)!r}")
    if g("protocol_sha256") != PROTOCOL_SHA256 or sha_obj(proto) != PROTOCOL_SHA256:
        void.append("scope: the banked protocol does not hash to the sealed PROTOCOL_SHA256")
    recipes = g("recipes") or {}
    if g("recipes_sha256") != RECIPES_SHA256 or sha_obj(recipes) != RECIPES_SHA256 or recipes != RECIPES:
        void.append("scope: the banked recipes are not the sealed M1, L3 and M4")
    if g("reference_top1") != REFERENCE_TOP1:
        void.append("scope: the banked in-distribution references are not the sealed ones")

    # ---- the extension corpus
    ext = g("ext_corpus") or {}
    for k, v in EXT.items():
        expect_eq(void, ext.get(k), v, f"extension corpus: ext_corpus.{k}")
    n_eval = PARTITION["n_eval_rows"]; n_all = n_eval + N_EXT
    if g("n_ext_rows") != N_EXT or g("n_eval_rows") != n_eval or g("n_ext_real_rows") != N_REAL:
        void.append(f"extension corpus: n_ext_rows={g('n_ext_rows')!r}, n_eval_rows={g('n_eval_rows')!r}, "
                    f"n_ext_real_rows={g('n_ext_real_rows')!r}")
    if g("ext_real_families") != REAL_FAMILIES or g("ext_synthetic_families") != SYNTH_FAMILIES:
        void.append("extension corpus: the banked real/synthetic family lists are not the sealed ones")
    if g("ext_label_histogram") != EXT_LABEL_HISTOGRAM:
        void.append("extension corpus: the banked label histogram is not the sealed one")

    # ---- sealed sets
    part = g("partition") or {}
    for k, v in PARTITION.items():
        expect_eq(void, part.get(k), v, f"sealed set: partition.{k}")
    for k in ("pool_chunks_shared_with_ext", "eval_chunks_shared_with_ext", "pool_rows_identical_to_an_ext_row",
              "eval_rows_identical_to_an_ext_row"):
        if part.get(k) != 0:
            void.append(f"leakage: partition.{k}={part.get(k)!r}, must be the measured 0")
    if part.get("null_labels_permuted") is not True or part.get("null_labels_same_multiset") is not True \
            or not isinstance(part.get("null_y_shuffled_sha256"), str):
        void.append("null control: the null block's labels are not banked as a permutation of the sealed labels")
    if g("complete") is not True or not isinstance(g("run_finished_utc"), str):
        void.append(f"complete: complete={g('complete')!r}, run_finished_utc={g('run_finished_utc')!r}; missing {g('missing_roles')!r}")
    if g("null_rows") != PROTOCOL["null_rows"]:
        void.append(f"null control: null_rows={g('null_rows')!r}")
    le = g("launch_environment") or {}
    if le.get("ok") is not True or le.get("problems") != [] or any((le.get("env") or {}).get(k) != v for k, v in ENV.items()):
        void.append("environment: launch_environment is not ok with the sealed environment")
    env = g("environment") or {}
    for k, v in ENV.items():
        if env.get(k) != v:
            void.append(f"environment: {k}={env.get(k)!r}, banked {v!r}")

    # ---- scores file: the vectors and the two arrays that bind every reading to the sealed corpus
    scores, ext_fam_idx, eci, eval_ids = {}, None, None, None
    if os.path.exists(SCORES):
        try:
            sd = json.load(open(SCORES, encoding="utf-8")) or {}
            scores = sd.get("per_example") or {}
            ext_fam_idx = sd.get("ext_fam"); eci = sd.get("ext_chunk_ids"); eval_ids = sd.get("eval_chunk_ids")
            if sd.get("eval_idx_sha256") != PARTITION["eval_idx_sha256"] or sd.get("smoke") is not False \
                    or sd.get("preregistration") != PREREG or sd.get("n_eval_rows") != n_eval or sd.get("n_ext_rows") != N_EXT \
                    or sd.get("ext_families") != EXT_FAMILIES \
                    or sd.get("ext_arrays_sha256") != {k: v["sha256"] for k, v in EXT["arrays"].items()}:
                void.append("scores: the scores file is not this run's, or is a smoke run's, or names a different extension corpus")
        except Exception:  # noqa: BLE001
            void.append("scores: the scores file is not JSON")
    else:
        void.append("scores: the scores file is absent")
    if not _ints(ext_fam_idx, N_EXT, set(range(len(EXT_FAMILIES)))):
        void.append("scores: ext_fam missing, not N_EXT long, or not family indices"); ext_fam_idx = None
    elif hashlib.sha256(bytes(ext_fam_idx)).hexdigest() != EXT["arrays"]["fam"]["sha256"]:
        void.append("scores: ext_fam does not hash to the sealed fam array"); ext_fam_idx = None
    if not _ints(eci, N_EXT):
        void.append("scores: ext_chunk_ids missing or not N_EXT long"); eci = None
    else:
        try:
            gb = b"".join(int(x).to_bytes(4, "little", signed=True) for x in eci)
        except OverflowError:
            gb = b""
        if hashlib.sha256(gb).hexdigest() != EXT["arrays"]["g"]["sha256"]:
            void.append("scores: ext_chunk_ids do not hash to the sealed g array")
        if min(eci) != EXT["chunk_id_min"] or max(eci) != EXT["chunk_id_max"] or min(eci) <= CORPUS["chunk_id_max"] \
                or len(set(eci)) != EXT["n_chunks"] or any(b > a for a, b in zip(eci[1:], eci[:-1])):
            void.append("scores: ext_chunk_ids are outside the sealed id range, not the sealed chunk count, or not in build order")
        if eci != [c for c, n in zip(EXT_CHUNK_IDS, EXT_ROWS_PER_CHUNK) for _ in range(n)]:
            void.append("scores: ext_chunk_ids are not the sealed chunk ids expanded by their sealed row counts")
        if ext_fam_idx is not None:
            if any((c - CHUNK_ID_BASE) // FAMILY_STRIDE != f for c, f in zip(eci, ext_fam_idx)):
                void.append("scores: an extension chunk id does not map to its row's family by the sealed base and stride")
            per = {f: set() for f in EXT_FAMILIES}
            for c, f in zip(eci, ext_fam_idx):
                per[EXT_FAMILIES[f]].add(c)
            if {f: len(s) for f, s in per.items()} != EXT["chunks_per_family"]:
                void.append("scores: distinct chunk ids per family are not the sealed chunks_per_family")
    if ext_fam_idx is not None:
        counts = {f: 0 for f in EXT_FAMILIES}
        for i in ext_fam_idx:
            counts[EXT_FAMILIES[i]] += 1
        if counts != EXT["rows_per_family"]:
            void.append(f"scores: ext_fam row counts {counts} are not the sealed rows_per_family")
    fam_e = None
    if not _ints(eval_ids, n_eval, None) or min(eval_ids) < CORPUS["chunk_id_min"] or max(eval_ids) > CORPUS["chunk_id_max"] \
            or len(set(eval_ids)) != PARTITION["n_eval_chunks"] \
            or sum(1 for c in eval_ids if c % len(FAMILIES) != 0) != PARTITION["n_eval_non_gutenberg"]:
        void.append("scores: eval_chunk_ids missing, not the sealed evaluation chunks, or not the sealed family mix")
    else:
        fam_e = [FAMILIES[int(c) % len(FAMILIES)] for c in eval_ids]
    ledger = g("ledger") or []
    fits = g("fits") or {}
    if not isinstance(fits, dict):
        void.append("fit: fits is not a mapping"); fits = {}

    def expected_fp(name):
        role = "null" if name == "null" else name
        cand = RECIPES["model"] if name == "null" else RECIPES[name]
        stage = "null" if name == "null" else "pool"
        rows = PARTITION["null_sorted_sha256"] if name == "null" else PARTITION["pool_idx_sha256"]
        return fingerprint(prereg=PREREG, seed=SEED, role=role, cand=cand, stage=stage, rows=rows,
                           eval=PARTITION["eval_idx_sha256"], ext=EXT["arrays"]["X"]["sha256"])

    completed_pos = {}

    def check_record(name, rec, role, rows_sha, sorted_sha, n_rows, stage):
        if not isinstance(rec, dict) or rec.get("status") != "fit":
            void.append(f"fit: {name} status {(rec or {}).get('status')!r}; must be 'fit'"); return
        if num(rec.get("top1")) is None or num(rec.get("top1_non_gutenberg")) is None or \
                not isinstance(rec.get("per_family"), dict) or len(rec["per_family"]) != 8 or \
                any(num(v) is None for v in rec["per_family"].values()):
            void.append(f"fit: {name} scores are not all finite")
        cand = RECIPES[role]
        if rec.get("id") != cand["id"] or rec.get("params_sha256") != RECIPE_SHA256[role] or rec.get("params") != cand["params"] \
                or rec.get("family") != cand["family"] or bool(rec.get("scaled")) != bool(cand.get("scaled", False)) \
                or rec.get("val") != cand.get("val") or rec.get("head") != ("null" if name == "null" else role):
            void.append(f"fit: {name} is not the sealed {cand['id']} (id, params, params hash, family, scaled, val or head off-recipe)")
        if rec.get("seed") != SEED or rec.get("n_fit_rows") != n_rows \
                or (rows_sha is not None and rec.get("fit_rows_sha256") != rows_sha) \
                or (sorted_sha is not None and rec.get("fit_rows_sorted_sha256") != sorted_sha):
            void.append(f"fit: {name} was not fitted on the sealed rows with the preregistered seed")
        if rec.get("stage") != stage:
            void.append(f"fit: {name} stage {rec.get('stage')!r} is not {stage!r}")
        if any(not rf.get("probe_ok") for rf in (rec.get("block_refills") or [])):
            void.append(f"fit: {name} banked a failed block probe check")
        n_iter = (rec.get("fit_info") or {}).get("n_iter")
        if not isinstance(n_iter, int) or isinstance(n_iter, bool):
            void.append(f"fit: {name} has no integer iteration count")
        renv = rec.get("environment") or {}
        for k, v in ENV.items():
            if renv.get(k) != v:
                void.append(f"environment: {name} {k}={renv.get(k)!r}, banked {v!r}")
        fp = expected_fp(name)
        if rec.get("fingerprint") != fp:
            void.append(f"fit: {name} fingerprint {rec.get('fingerprint')!r} is not the one recomputed from the sealed literals")
        done = [i for i, e in enumerate(ledger) if isinstance(e, dict) and e.get("name") == name and e.get("event") == "completed"]
        if len(done) != 1:
            void.append(f"fit: {name} has {len(done)} ledger completions, must be exactly 1")
        else:
            ce = ledger[done[0]]
            if ce.get("fingerprint") != fp:
                void.append(f"fit: {name}'s completion event does not carry the sealed fingerprint")
            if not any(isinstance(e, dict) and e.get("name") == name and e.get("event") == "started" and e.get("fingerprint") == fp
                       for e in ledger[:done[0]]):
                void.append(f"fit: {name} has no 'started' event with its fingerprint before its completion")
            completed_pos[name] = done[0]
        pe = scores.get(name)
        if not _ints(pe, n_all, (0, 1)):
            void.append(f"fit: {name} per-example vector missing, not {n_all} long, or not in {{0, 1}}"); return
        if rec.get("per_example_sha256") != hashlib.sha256(bytes(pe)).hexdigest():
            void.append(f"fit: {name} per_example_sha256 is not the hash of its banked vector")
        if num(rec.get("top1")) != mean4(pe):
            void.append(f"fit: {name} record top1 {rec.get('top1')!r} is not its vector's mean {mean4(pe)!r}")
        if fam_e is not None:
            ng = [pe[i] for i in range(n_eval) if fam_e[i] != "gutenberg"] + pe[n_eval:]
            if num(rec.get("top1_non_gutenberg")) != mean4(ng):
                void.append(f"fit: {name} record top1_non_gutenberg is not its vector's non-gutenberg mean")
            pf = {f: mean4([pe[i] for i in range(n_eval) if fam_e[i] == f]) for f in FAMILIES}
            if rec.get("per_family") != pf:
                void.append(f"fit: {name} record per_family is not its vector's per-family means over the sealed evaluation rows")

    for r in ROLES:
        check_record(r, fits.get(r), r, PARTITION["pool_idx_sha256"], PARTITION["pool_sorted_sha256"], PARTITION["n_pool_rows"], "pool")
    nc = fits.get("null") or {}
    check_record("null", nc, "model", None, PARTITION["null_sorted_sha256"], PROTOCOL["null_rows"], "null")
    if g("null_control") != nc:
        void.append("null control: null_control is not the banked null record")
    if len(completed_pos) == 4 and [completed_pos[n] for n in ORDER] != sorted(completed_pos[n] for n in ORDER):
        void.append("fit: the ledger's completions are not in the sealed order null, incumbent, logistic_l3, model")
    if g("fit_info_by_role") != {r: (fits.get(r) or {}).get("fit_info") for r in ROLES}:
        void.append("fit: fit_info_by_role is not the records' fit_info")

    # ---- every reading re-derived from the per-example vectors and the sealed family array
    reads = g("readings") or {}
    rec_reads = {}
    if ext_fam_idx is not None and fam_e is not None and not any(m.startswith("fit:") or m.startswith("scores:") for m in void):
        fam_x = [EXT_FAMILIES[i] for i in ext_fam_idx]
        real_rows = set(REAL_FAMILIES); synth_rows = set(SYNTH_FAMILIES)
        for name in ORDER:
            v = scores[name]; rep, ex = v[:n_eval], v[n_eval:]
            by = {f: [] for f in EXT_FAMILIES}
            for i in range(N_EXT):
                by[fam_x[i]].append(ex[i])
            real = [x for f in REAL_FAMILIES for x in by[f]]; synth = [x for f in SYNTH_FAMILIES for x in by[f]]
            rr = {"reproduction_top1": mean4(rep), "reproduction_correct": sum(rep),
                  "ext_top1": mean4(ex), "ext_correct": sum(ex), "n_ext_rows": N_EXT,
                  "ext_per_family": {f: mean4(by[f]) for f in EXT_FAMILIES},
                  "ext_per_family_correct": {f: sum(by[f]) for f in EXT_FAMILIES},
                  "ext_structured_text_top1": mean4([x for f in STRUCTURED_TEXT for x in by[f]]),
                  "ext_high_entropy_top1": mean4([x for f in HIGH_ENTROPY for x in by[f]]),
                  "ext_real_top1": mean4(real), "ext_real_correct": sum(real), "n_ext_real_rows": len(real),
                  "ext_synthetic_correct": sum(synth), "ext_synthetic_top1": mean4(synth),
                  "reproduction_per_family": {f: mean4([rep[i] for i in range(n_eval) if fam_e[i] == f]) for f in FAMILIES}}
            if len(real) != N_REAL:
                void.append(f"readings: the sealed family array gives {len(real)} real-family rows, not {N_REAL}")
            rec_reads[name] = rr
            banked = reads.get(name) or {}
            for k, val in rr.items():
                if banked.get(k) != val:
                    void.append(f"readings: {name}.{k}={banked.get(k)!r} is not the reader's recomputation {val!r}")
        for r in ROLES:
            if num((g("reproduction_top1") or {}).get(r)) != rec_reads[r]["reproduction_top1"]:
                void.append(f"reproduction: reproduction_top1.{r} is not the recomputed value")
            if num((g("ext_top1") or {}).get(r)) != rec_reads[r]["ext_top1"] or (g("ext_correct") or {}).get(r) != rec_reads[r]["ext_correct"]:
                void.append(f"readings: ext_top1.{r} or ext_correct.{r} is not the recomputed value")
            if num((g("ext_real_top1") or {}).get(r)) != rec_reads[r]["ext_real_top1"] or (g("ext_real_correct") or {}).get(r) != rec_reads[r]["ext_real_correct"]:
                void.append(f"readings: ext_real_top1.{r} or ext_real_correct.{r} is not the recomputed value")
            if (g("ext_per_family") or {}).get(r) != rec_reads[r]["ext_per_family"]:
                void.append(f"readings: ext_per_family.{r} is not the recomputed value")
            drift = round(abs(rec_reads[r]["reproduction_top1"] - REFERENCE_TOP1[r]), 6)
            if drift > REPRODUCTION_TOLERANCE:
                void.append(f"reproduction: {r} on the full pool scores {rec_reads[r]['reproduction_top1']} against the banked "
                            f"{REFERENCE_TOP1[r]}; the pool, the evaluation set or the machinery is not 0014's")
        if num(g("ext_top1_model")) != rec_reads["model"]["ext_top1"] or g("ext_correct_model") != rec_reads["model"]["ext_correct"] \
                or g("ext_real_correct_model") != rec_reads["model"]["ext_real_correct"]:
            void.append("readings: ext_top1_model, ext_correct_model or ext_real_correct_model is not the recomputed value")
        mc, lc, ic = (rec_reads[r]["ext_correct"] for r in ("model", "logistic_l3", "incumbent"))
        if num(g("ext_margin_model_over_logistic_l3_exact")) != round((mc - lc) / N_EXT, 6):
            void.append("margin: ext_margin_model_over_logistic_l3_exact is not (correct counts difference) / N_EXT")
        if num(g("ext_margin_model_over_incumbent_exact")) != round((mc - ic) / N_EXT, 6):
            void.append("margin: ext_margin_model_over_incumbent_exact is not (correct counts difference) / N_EXT")
        null_ext = rec_reads["null"]["ext_top1"]; null_eval = rec_reads["null"]["reproduction_top1"]
        if num(g("shuffled_label_accuracy_ext")) != null_ext or num(g("shuffled_label_accuracy_eval")) != null_eval:
            void.append("null control: shuffled_label_accuracy_ext or shuffled_label_accuracy_eval is not the recomputed value")
        elif null_ext > CHANCE + NULL_TOLERANCE or null_eval > CHANCE + NULL_TOLERANCE:
            void.append(f"null control: shuffled labels reached {null_ext} on the extension rows and {null_eval} on the sealed rows, "
                        f"against chance {CHANCE} + {NULL_TOLERANCE} — the pipeline leaks")
    elif not void:
        void.append("readings: the reader could not recompute the readings")

    # ---- the one clause, on the reader's own count of M4's correct real-family rows
    fails: list[str] = []
    mreal = rec_reads.get("model", {}).get("ext_real_correct") if not void else None
    if not void and mreal < MIN_CORRECT_REAL:
        fails.append(f"transfer: M4's correct real-family rows {mreal} of {N_REAL} ({rec_reads['model']['ext_real_top1']}) is below "
                     f"{MIN_CORRECT_REAL} (chance {CHANCE} + {BAR} = {MIXTURE_MUST_REACH})")

    flags = None
    if not void:
        need = lambda n: math.ceil(n * (1.0 / 26 + BAR) - 1e-9)  # noqa: E731
        rm = rec_reads["model"]; rl = rec_reads["logistic_l3"]; ri = rec_reads["incumbent"]
        flags = {"mixture_reaches_bar": rm["ext_correct"] >= MIN_CORRECT, "mixture_min_correct": MIN_CORRECT,
                 "logistic_l3_reaches_bar_real": rl["ext_real_correct"] >= MIN_CORRECT_REAL,
                 "incumbent_reaches_bar_real": ri["ext_real_correct"] >= MIN_CORRECT_REAL,
                 "synthetic_reaches_bar": rm["ext_synthetic_correct"] >= need(N_EXT - N_REAL),
                 "synthetic_min_correct": need(N_EXT - N_REAL),
                 "model_leads_logistic_l3_real_rows": rm["ext_real_correct"] - rl["ext_real_correct"],
                 "model_leads_incumbent_real_rows": rm["ext_real_correct"] - ri["ext_real_correct"],
                 "model_leads_logistic_l3_by_0.02": rm["ext_real_correct"] - rl["ext_real_correct"] >= math.ceil(0.02 * N_REAL - 1e-9),
                 "model_leads_incumbent_by_0.02": rm["ext_real_correct"] - ri["ext_real_correct"] >= math.ceil(0.02 * N_REAL - 1e-9),
                 "model_leads_logistic_l3_by_0.05": rm["ext_real_correct"] - rl["ext_real_correct"] >= math.ceil(0.05 * N_REAL - 1e-9),
                 "model_leads_incumbent_by_0.05": rm["ext_real_correct"] - ri["ext_real_correct"] >= math.ceil(0.05 * N_REAL - 1e-9),
                 "per_family_min_correct": {f: need(EXT["rows_per_family"][f]) for f in EXT_FAMILIES},
                 "families_where_model_reaches_bar": [f for f in EXT_FAMILIES
                                                      if rm["ext_per_family_correct"][f] >= need(EXT["rows_per_family"][f])],
                 "reproduction_exact": {r: round(rec_reads[r]["reproduction_top1"] - REFERENCE_TOP1[r], 6) == 0.0 for r in ROLES},
                 "n_iter_by_role": {r: (fits[r].get("fit_info") or {}).get("n_iter") for r in ROLES},
                 "at_iteration_cap": {r: (fits[r].get("fit_info") or {}).get("n_iter") >= MAX_ITER[r] for r in ROLES}}

    if void:
        verdict, meaning = "VOID", ("A validity or control clause fails, or the artifact is incomplete. This run says nothing "
                                    "about transfer outside the builder in either direction.")
    elif fails:
        verdict, meaning = "OOB_TRANSFER_FAILS", (
            f"At 4096 bytes, 0014's searched model, fitted on the builder's eight families, does not identify the encoder at "
            f"chance + {BAR} on the mixture over the five pinned real-file families the builder never produced: {mreal} of {N_REAL} "
            f"real-family rows correct ({rec_reads['model']['ext_real_top1']}) against {MIN_CORRECT_REAL} needed. A bound on the "
            "headline recipe's reach outside the builder for these five families as pinned; the per-family readings, the synthetic "
            "flag and the ceilings banked beside it say where the reading comes from. Nothing here revises 0003, 0014, 0015, 0016 "
            "or 0017, and nothing here establishes a buyer.")
    else:
        verdict, meaning = "OOB_TRANSFERS", (
            f"At 4096 bytes, 0014's searched model, fitted on the builder's eight families, identifies the encoder at chance + {BAR} "
            f"or better on the mixture over the five pinned real-file families the builder never produced: {mreal} of {N_REAL} "
            f"real-family rows correct ({rec_reads['model']['ext_real_top1']}) against {MIN_CORRECT_REAL} needed, not necessarily "
            "on every family (the per-family readings say which). The first preregistered transfer reading in this record taken "
            "outside the builder, for these five families as pinned. Nothing here revises 0003, 0014, 0015, 0016 or 0017, and "
            "nothing here establishes a buyer.")

    result = {
        "schema": "raise-v1/oob_4096_reread_verdict/1",
        "preregistration": REREAD, "reads_artifact_of": PREREG, "source_artifact": os.path.relpath(ARTIFACT, REPO),
        "verdict": verdict, "meaning": meaning,
        "validity_failed_clauses": void, "transfer_failed_clauses": fails,
        "bar_applied": {"chance": CHANCE, "bar": BAR, "mixture_must_reach": MIXTURE_MUST_REACH, "min_correct_real": MIN_CORRECT_REAL,
                        "n_real_rows": N_REAL, "min_correct": MIN_CORRECT, "n_ext_rows": N_EXT, "flags": flags},
        "ext_real_top1_model": rec_reads["model"]["ext_real_top1"] if not void else None,
        "ext_real_correct_model": mreal if not void else None,
        "ext_top1_model": rec_reads["model"]["ext_top1"] if not void else None,
        "ext_correct_model": rec_reads["model"]["ext_correct"] if not void else None,
        "ext_top1": {r: rec_reads[r]["ext_top1"] for r in ROLES} if not void else None,
        "ext_correct": {r: rec_reads[r]["ext_correct"] for r in ROLES} if not void else None,
        "ext_real_top1": {r: rec_reads[r]["ext_real_top1"] for r in ROLES} if not void else None,
        "ext_real_correct": {r: rec_reads[r]["ext_real_correct"] for r in ROLES} if not void else None,
        "ext_per_family": {r: rec_reads[r]["ext_per_family"] for r in ROLES} if not void else None,
        "ext_subsets": {r: {k: rec_reads[r][k] for k in ("ext_structured_text_top1", "ext_high_entropy_top1", "ext_real_top1",
                                                         "ext_synthetic_top1")} for r in ROLES} if not void else None,
        "ext_margin_model_over_logistic_l3_exact": num(g("ext_margin_model_over_logistic_l3_exact")) if not void else None,
        "ext_margin_model_over_incumbent_exact": num(g("ext_margin_model_over_incumbent_exact")) if not void else None,
        "ext_real_mixture_minus_chance_model": round(rec_reads["model"]["ext_real_top1"] - CHANCE, 6) if not void else None,
        "reproduction_top1": {r: rec_reads[r]["reproduction_top1"] for r in ROLES} if not void else None,
        "reproduction_drift": {r: round(rec_reads[r]["reproduction_top1"] - REFERENCE_TOP1[r], 6) for r in ROLES} if not void else None,
        "reference_top1": REFERENCE_TOP1,
        "shuffled_label_accuracy_ext": rec_reads["null"]["ext_top1"] if not void else None,
        "shuffled_label_accuracy_eval": rec_reads["null"]["reproduction_top1"] if not void else None,
        "ext_ceiling_distinct_fragments": EXT_CEILING_FRAGMENTS,
        "ext_rows_per_family": EXT["rows_per_family"],
        "fit_info_by_role": g("fit_info_by_role"),
        "informational_only": "the flags, the per-family and subset readings, the eight-family mixture, the margins, the reproduction "
                              "drifts, the ceilings and the artifact's cluster intervals are informational: not a verdict, not quotable "
                              "as a pass. The verdict is the `verdict` field.",
        "establishes_a_buyer": False, "revises_0003_0014_0015_0016_0017": False,
        "read": {k: g(k) for k in (
            "preregistration", "smoke", "stage", "complete", "missing_roles", "ext_real_correct_model", "ext_top1_model",
            "ext_correct_model", "ext_real_top1", "ext_top1", "reproduction_top1", "ext_margin_model_over_logistic_l3_exact",
            "ext_margin_model_over_incumbent_exact", "shuffled_label_accuracy_ext", "shuffled_label_accuracy_eval",
            "chance_accuracy", "null_rows", "n_ext_rows", "n_ext_real_rows", "n_classes")},
        "readings_banked": reads,
    }
    _write(result)

    print("READER 0019 — re-read of 0018's banked artifact (out-of-builder transfer at 4096)")
    for k, v in result["read"].items():
        print(f"  {k:<40} {v}")
    print(f"  ext_per_family (model)                   {json.dumps((reads.get('model') or {}).get('ext_per_family'))}")
    if void:
        print(f"\n  VALIDITY FAILED CLAUSES ({len(void)}):")
        for f in void:
            print(f"    · {f}")
    if fails:
        print(f"\n  TRANSFER FAILED CLAUSES ({len(fails)}):")
        for f in fails:
            print(f"    · {f}")
    print(f"\n  VERDICT: {verdict}")
    print(f"  {meaning}")
    print("  This does not establish a buyer, and was never capable of doing so.")
    print(f"  wrote {os.path.relpath(OUT, REPO)}")
    return 0


